contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(recipient != address(0));
        require(address(this).balance >= 100);

        uint balBefore = address(c).balance;
        uint recvBefore = recipient.balance;

        bool reverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;
        uint recvAfter = recipient.balance;

        assert(!reverted || (balAfter == balBefore && recvAfter == recvBefore));
    }
}

